  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─────────────────────────────────────────────\n// USUARIOS Y AUTENTICACIÓN\n// ─────────────────────────────────────────────\n\nmodel Usuario {\n  id       Int      @id @default(autoincrement())\n  nombre   String\n  email    String   @unique\n  password String\n  rol      Rol      @default(USUARIO)\n  activo   Boolean  @default(true)\n  creadoEn DateTime @default(now())\n\n  compras Compra[]\n}\n\nenum Rol {\n  ADMIN\n  USUARIO\n}\n\n// ─────────────────────────────────────────────\n// CONFIGURACIÓN EDITABLE DEL SITIO\n// claves: hero_titulo, hero_subtitulo, hero_descripcion,\n//         instagram_url, whatsapp_numero, popup_texto, popup_instagram\n// ─────────────────────────────────────────────\n\nmodel Configuracion {\n  id            Int      @id @default(autoincrement())\n  clave         String   @unique\n  valor         String\n  actualizadoEn DateTime @updatedAt\n}\n\n// ─────────────────────────────────────────────\n// FASES DEL MÉTODO\n// Las 6 fases son categorías del método de Flowness\n// Cada fase tiene un video corto de muestra\n// ─────────────────────────────────────────────\n\nmodel Fase {\n  id          Int      @id @default(autoincrement())\n  numero      Int      @unique\n  nombre      String\n  descripcion String\n  videoUrl    String?\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n\n  clases Clase[]\n}\n\n// ─────────────────────────────────────────────\n// CLASES\n// Pertenecen a una Fase del método\n// La primera clase es gratis para usuarios registrados\n// Las demás se habilitan al comprar\n// ─────────────────────────────────────────────\n\nmodel Clase {\n  id          Int      @id @default(autoincrement())\n  faseId      Int\n  nombre      String\n  descripcion String\n  videoUrl    String?\n  precio      Float    @default(0)\n  esGratis    Boolean  @default(false)\n  orden       Int      @default(0)\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n\n  fase       Fase        @relation(fields: [faseId], references: [id])\n  compras    Compra[]\n  documentos Documento[]\n}\n\n// ─────────────────────────────────────────────\n// COMPRAS\n// ─────────────────────────────────────────────\n\nmodel Compra {\n  id        Int        @id @default(autoincrement())\n  usuarioId Int\n  claseId   Int\n  monto     Float\n  estado    EstadoPago @default(PENDIENTE)\n  mpPagoId  String?\n  creadoEn  DateTime   @default(now())\n\n  usuario Usuario @relation(fields: [usuarioId], references: [id])\n  clase   Clase   @relation(fields: [claseId], references: [id])\n}\n\nenum EstadoPago {\n  PENDIENTE\n  APROBADO\n  RECHAZADO\n}\n\n// ─────────────────────────────────────────────\n// DOCUMENTOS (PDFs adjuntos a clases)\n// ─────────────────────────────────────────────\n\nmodel Documento {\n  id          Int      @id @default(autoincrement())\n  claseId     Int\n  titulo      String\n  descripcion String?\n  url         String\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n\n  clase Clase @relation(fields: [claseId], references: [id])\n}\n\n// ─────────────────────────────────────────────\n// GALERÍA DE FOTOS\n// ─────────────────────────────────────────────\n\nmodel Foto {\n  id          Int      @id @default(autoincrement())\n  url         String\n  descripcion String?\n  orden       Int      @default(0)\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n}\n\n// ─────────────────────────────────────────────\n// SOBRE MÍ (info de la instructora)\n// ─────────────────────────────────────────────\n\nmodel SobreMi {\n  id            Int      @id @default(autoincrement())\n  nombre        String\n  titulo        String\n  descripcion1  String\n  descripcion2  String\n  fotoUrl       String?\n  actualizadoEn DateTime @updatedAt\n}\n\n// ─────────────────────────────────────────────\n// AVISOS\n// ─────────────────────────────────────────────\n\nmodel Aviso {\n  id          Int      @id @default(autoincrement())\n  titulo      String\n  descripcion String\n  activo      Boolean  @default(true)\n  creadoEn    DateTime @default(now())\n}\n",
